package quebec.culture.donnees;
import android.app.*;import android.content.*;import android.os.*;import android.widget.*;
public class ProjectTimelineActivity extends Activity{private final String[] phases={"Inventaire et sauvegarde de la base existante","Cartographie vers la norme sectorielle","Nettoyage et normalisation","Validation humaine et contrôle qualité","Export interopérable et documentation","Partage / données ouvertes si les droits le permettent","Mesure des résultats et reddition de comptes"};private SharedPreferences p;@Override public void onCreate(Bundle b){super.onCreate(b);Ui.bars(this);p=getSharedPreferences("timeline",0);LinearLayout r=Ui.root(this);r.addView(Ui.text(this,"Échéancier du projet",28,true));r.addView(Ui.text(this,"Planifier le projet sur un maximum de 12 mois et conserver une preuve de chaque livrable.",14,false));for(int i=0;i<phases.length;i++){final int n=i;LinearLayout box=Ui.panel(this);CheckBox c=new CheckBox(this);c.setText(phases[i]);c.setChecked(p.getBoolean("done"+i,false));box.addView(c);EditText m=Ui.field(this,"Mois prévus (ex. 1–2)",p.getString("months"+i,""));box.addView(m);EditText note=Ui.field(this,"Livrable, responsable et preuve",p.getString("note"+i,""));box.addView(note);Button save=Ui.secondary(this,"Enregistrer cette étape");save.setOnClickListener(v->p.edit().putBoolean("done"+n,c.isChecked()).putString("months"+n,m.getText().toString()).putString("note"+n,note.getText().toString()).apply());box.addView(save);r.addView(box);}Button team=Ui.primary(this,"Équipe et capacité de réalisation");team.setOnClickListener(v->startActivity(new Intent(this,TeamCapacityActivity.class)));r.addView(team);setContentView(Ui.wrap(this,r));}}
